# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
# acs-version: 0.18.0
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.18.0/acs-0.18.0-aarch64-apple-darwin.tar.gz"
      sha256 "597d96feb7c70138477c177d0a55234965dc5488da9acecff3cb8b205e46c123"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.18.0/acs-0.18.0-x86_64-apple-darwin.tar.gz"
      sha256 "b7daafcafa5f51ece4b954c6899cbb293e49e6a2a35091b5d0652f03c2eed1df"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.18.0/acs-0.18.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "9e1698e27b9a533bcda1d875739199b28eedf9432d166fc202f09c6350737f0f"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.18.0/acs-0.18.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "ad9374a8d62cf2abd8912f71849ffe340a496de3723e38c08d38f379b3c98fe3"
    end
  end

  def install
    bin.install "acs"
    bin.install_symlink "acs" => "acscp"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
    assert_match "acs #{version} ", shell_output("#{bin}/acscp --version")
  end
end
